_ALERT = _prog("import string\nsafe = string.ascii_letters + string.digits + ' .,;-_/:?@()'\nmsg = \"x'; reboot; '\"\n"
               "text = \"'\" + ''.join(c for c in msg if c in safe) + \"'\"\nresult = 'myemailscript.sh \"Alert: %s\"'.replace('%s', text)")
_HELP = _ev("help_bitcoind_31_1_v1_0_0.txt")
