 (_has(_VERIFY, "releases are signed by a number of public keys on the basis of the [guix.sigs repository]",
       "you (the end user) decide which of these public keys you trust", "The downloaded binaries are then hashed and compared to the signed checksum file",
       "It first checks if the checksum file is valid based upon a plurality of signatures", "--min-good-sigs 10", "--trusted-keys"), "True"),
 (_has(_GUIX, "to _audit and reproduce_ our toolchain instead of blindly _trusting_ binary downloads", "We achieve bootstrappability by using Guix as a functional package manager",
       "the shasums of the build outputs are gathered into files named `SHA256SUMS`", "Guix build outputs are attested to in the [`guix.sigs` repository]",
       "guix-verify", "Override the reference UNIX timestamp used for bit-for-bit reproducibility"), "True"),
 (_has(_RELPROC, "git clone https://github.com/bitcoin-core/guix.sigs.git", "Build and attest to build outputs", "noncodesigned.SHA256SUMS{,.asc}"), "True"),
 # checksum
 (_has(_src("rfc6234.txt"), "these algorithms, the result is an output called a message digest", "Any change to a message in transit will, with very high probability, result in a different message digest",
       "it is computationally infeasible to (1) find a message that corresponds to a given message digest", '#define TEST1 "abc"', '"BA7816BF8F01CFEA4141" "40DE5DAE2223B00361A396177A9CB410FF61F20015AD"'), "True"),
 ("__import__('hashlib').sha256(b'abc').hexdigest().upper() == 'BA7816BF8F01CFEA4141' + '40DE5DAE2223B00361A396177A9CB410FF61F20015AD'", "True"),
 ("(len(__import__('hashlib').sha256(b'abc').digest()), len(__import__('hashlib').sha256(b'abc').hexdigest()), len(__import__('hashlib').sha256(b'a' * 10**6).digest()))", "(32, 64, 32)"),
 (_prog("import hashlib\na = hashlib.sha256(b'abc').hexdigest()\nb = hashlib.sha256(b'abd').hexdigest()\nresult = (a[:16], b[:16], sum(x != y for x, y in zip(a, b)), 64 * 15 // 16)"), "('ba7816bf8f01cfea', 'a52d159f262b2c6d', 58, 60)"),
 # signatures
 (_has(_src("rfc9580.txt"), "This document specifies the message formats used in OpenPGP", "OpenPGP provides encryption with public key or symmetric cryptographic algorithms, digital signatures, compression, and key management",
       'Some OpenPGP applications use so-called "detached signatures"', "These detached signatures are simply one or more Signature packets stored separately from the data for which they are a signature",
       "Key Expiration Time", "revocation"), "True"),
 # package registries / toolkits
 ("(sorted({e['registry'] for e in %s['entries'].values()}), len(%s['entries']), %s['queried'])" % (_REGJ, _REGJ, _REGJ),
  "(['Go module proxy', 'Maven Central', 'NuGet', 'PyPI', 'crates.io', 'npm'], 10, '2026-10-02')"),
